<script setup>
import { computed, ref } from 'vue';
import { useForm } from '@inertiajs/vue3';
import axios from 'axios';
import { Truck, RefreshCw, Link2 } from '@lucide/vue';
const props=defineProps({order:Object});
const booking=useForm({provider:props.order.courier_provider||'steadfast',weight:0.5,area_id:'',area_name:''});
const syncing=useForm({});const attach=useForm({consignment_id:'',confirmed:false});
const areas=ref([]),areaSearch=ref(''),loadingAreas=ref(false),areaError=ref('');
const availableAreas=computed(()=>areas.value.filter(a=>`${a.name} ${a.district}`.toLowerCase().includes(areaSearch.value.toLowerCase())));
const blocked=computed(()=>props.order.shipment && props.order.shipment.state!=='rejected');
const eligible=computed(()=>props.order.stock_reserved && !['cancelled','completed','on_hold'].includes(props.order.status) && (props.order.payment_method==='cash_on_delivery'||props.order.payment_status==='paid'));
async function loadAreas(){loadingAreas.value=true;areaError.value='';try{areas.value=(await axios.get('/admin/courier/redx/areas')).data.areas||[];}catch{areaError.value='Unable to load delivery areas. Save your REDX credentials in Courier setup first.';}finally{loadingAreas.value=false;}}
function book(){const area=areas.value.find(a=>Number(a.id)===Number(booking.area_id));booking.area_name=area?.name||'';booking.post(`/admin/orders/${props.order.id}/courier`,{preserveScroll:true});}
function sync(){syncing.post(`/admin/orders/${props.order.id}/courier/sync`,{preserveScroll:true});}
function reconcile(){attach.post(`/admin/orders/${props.order.id}/courier/attach`,{preserveScroll:true});}
</script>
<template>
<section class="courier-booking panel no-print">
<header><span class="courier-icon"><Truck :size="20" /></span><div><h2>Courier delivery</h2><p>Book this order with your configured courier account.</p></div></header>
<div v-if="order.shipment" class="shipment-summary"><div><small>Provider</small><strong>{{ order.shipment.provider }}</strong></div><div><small>Booking</small><strong>{{ order.shipment.state }}</strong></div><div><small>Consignment</small><strong>{{ order.shipment.consignment_id || 'Not confirmed' }}</strong></div><div><small>Courier status</small><strong>{{ order.shipment.remote_status || 'Awaiting response' }}</strong></div><div><small>Amount to collect</small><strong>৳{{ Number(order.shipment.cod_amount).toLocaleString() }}</strong></div></div>
<form v-if="!blocked && eligible" @submit.prevent="book">
<div class="booking-fields"><label>Courier<select v-model="booking.provider"><option value="steadfast">Steadfast</option><option value="pathao">Pathao</option><option value="redx">REDX</option></select></label><label>Parcel weight (kg)<input v-model="booking.weight" type="number" min="0.1" max="10" step="0.1" required /></label></div>
<div v-if="booking.provider==='redx'" class="redx-area"><button class="btn secondary" type="button" :disabled="loadingAreas" @click="loadAreas">{{ loadingAreas?'Loading areas…':'Load REDX delivery areas' }}</button><p v-if="areaError" class="courier-error">{{ areaError }}</p><template v-if="areas.length"><label>Search delivery area<input v-model="areaSearch" placeholder="Area or district" /></label><label>Delivery area<select v-model="booking.area_id" required><option value="">Choose the customer’s delivery area</option><option v-for="area in availableAreas" :key="area.id" :value="area.id">{{ area.name }}{{ area.district?' · '+area.district:'' }}</option></select></label></template></div>
<p class="booking-note">Recipient name, phone, address and parcel details will be sent to the selected courier. Amount to collect: <strong>৳{{ Number(order.payment_status==='paid'?0:order.total).toLocaleString() }}</strong>. Pathao resolves the delivery area from the full address.</p>
<p v-for="(error,key) in booking.errors" :key="key" class="courier-error">{{ error }}</p>
<button class="btn primary" type="submit" :disabled="booking.processing || (booking.provider==='redx'&&!booking.area_id)"><Truck :size="16" />{{ booking.processing?'Booking…':'Book courier' }}</button>
</form>
<p v-else-if="!blocked" class="booking-note">Booking is available for active COD orders or orders with verified online payment and reserved stock.</p>
<div v-if="order.shipment?.state==='booked'" class="sync-actions"><button class="btn secondary" type="button" :disabled="syncing.processing" @click="sync"><RefreshCw :size="16" />{{ syncing.processing?'Refreshing…':'Refresh courier status' }}</button><small v-if="order.shipment.synced_at">Last checked {{ new Date(order.shipment.synced_at).toLocaleString() }}</small><p v-for="(error,key) in syncing.errors" :key="key" class="courier-error">{{ error }}</p><p class="booking-note">Courier returns and partial deliveries are held for manual review; stock is not automatically restored.</p></div>
<form v-if="['unknown','creating'].includes(order.shipment?.state)" @submit.prevent="reconcile" class="reconcile"><h3>Check the merchant portal first</h3><p class="booking-note">The result is uncertain. Do not create another parcel. If it exists in your courier portal, enter its consignment ID here. Stalled requests can be linked after two minutes.</p><label>Existing consignment ID<input v-model="attach.consignment_id" required maxlength="100" /></label><label class="confirm-link"><input v-model="attach.confirmed" type="checkbox" required /> I checked that this parcel belongs to this order.</label><p v-for="(error,key) in attach.errors" :key="key" class="courier-error">{{ error }}</p><button class="btn secondary" :disabled="attach.processing"><Link2 :size="16" />Link existing parcel</button></form>
</section>
</template>
<style scoped>
.courier-booking{padding:24px;margin-bottom:24px;border:1px solid #e3ebe7;border-radius:16px}.courier-booking header{display:flex;gap:12px;align-items:center;margin-bottom:22px}.courier-icon{display:grid;place-items:center;background:#e9f3ed;color:#23715c;width:42px;height:42px;border-radius:12px}.courier-booking h2{font-size:19px;font-weight:700}.courier-booking header p,.booking-note{font-size:12px;color:#708178;line-height:1.7;margin-top:6px}.booking-fields,.shipment-summary{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin-bottom:16px}.shipment-summary{grid-template-columns:repeat(auto-fit,minmax(145px,1fr));padding:16px;background:#f5f8f6;border-radius:12px}.shipment-summary small{display:block;color:#75877d;font-size:11px}.shipment-summary strong{display:block;margin-top:6px;font-size:13px;overflow-wrap:anywhere}.courier-booking label{display:flex;flex-direction:column;gap:8px;font-size:12px;font-weight:600}.courier-booking input:not([type=checkbox]),.courier-booking select{width:100%;padding:11px 12px;border:1px solid #dce6df;border-radius:8px;background:white;font:inherit;color:#243c30}.courier-booking .btn{margin-top:14px}.redx-area label{margin-top:12px}.courier-error{color:#aa3444;font-size:12px;margin-top:8px}.sync-actions small{display:block;color:#74837a;font-size:11px;margin-top:10px}.reconcile{border-top:1px solid #e3ebe7;margin-top:18px;padding-top:18px}.confirm-link{flex-direction:row!important;align-items:center;margin-top:12px}.booking-note{margin:12px 0}.courier-booking h3{font-weight:700}@media(max-width:600px){.courier-booking{padding:18px}.booking-fields{grid-template-columns:1fr}}
</style>
